INSERT IGNORE INTO restaurants (id, name, address, latitude, longitude, description, type, supported_dishes, created_at) VALUES
(1, 'Nhà Hàng Chay Ưu Đàm (U Dam Chay)', '34 Hàng Bài, Hoàn Kiếm, Hà Nội', 21.023300, 105.852500, 'Không gian ẩm thực Phật giáo thanh tịnh, thiết kế kiến trúc ba tầng độc đáo, các món chay kết hợp tinh tế giữa nguyên liệu truyền thống và hiện đại.', 'Nhà hàng chay cao cấp', 'Phở chay nấm đùi gà, Lẩu nấm cung đình Ưu Đàm, Cơm lá sen hạt điều, Nem nấm chiên xù', NOW()),
(2, 'Nhà Hàng Chay Sadhu', '87 Lý Thường Kiệt, Cửa Nam, Hoàn Kiếm, Hà Nội', 21.024800, 105.845600, 'Mô hình buffet chay gọi món cao cấp tại bàn với thực đơn hơn 60 món ăn mỹ vị, mang lại cảm giác bình an và trọn vẹn vị giác.', 'Buffet chay cao cấp', 'Súp bí đỏ kem nấm, Bánh đúc nóng Sadhu, Cơm rang nấm truffle, Chè hạt sen nhãn nhục', NOW()),
(3, 'Quán Cơm Chay Nàng Sen', '120 Yên Lãng, Đống Đa, Hà Nội', 21.011800, 105.815200, 'Quán chay ấm cúng bình dân phục vụ cơm suất và các món chay dinh dưỡng cho dân văn phòng và gia đình hàng ngày.', 'Quán chay bình dân', 'Cơm suất thập cẩm nấm kho, Đậu hũ sốt cà chua, Canh chua bông so đũa, Giò nấm chay luộc', NOW()),
(4, 'Hum Vegetarian - Lounge & Restaurant', '2 Thi Sách, Bến Nghé, Quận 1, TP. Hồ Chí Minh', 10.777900, 106.705100, 'Nhà hàng chay nổi tiếng bậc nhất Sài Gòn với phong cách ẩm thực thanh lịch, nguyên liệu rau củ hữu cơ tươi ngon theo mùa.', 'Nhà hàng chay cao cấp', 'Gỏi cuốn nấm nướng sốt tương đậu, Cà ri xanh rau củ nước cốt dừa, Cơm chiên trái dứa, Canh nấm sả ớt', NOW()),
(5, 'Pi Vegetarian Bistro', '19 Võ Văn Tần, Phường 6, Quận 3, TP. Hồ Chí Minh', 10.776100, 106.691700, 'Phong cách mộc mạc ấm áp như căn bếp gia đình, món chay đậm đà bản sắc Đông Nam Á, được giới trẻ và du khách quốc tế rất ưa chuộng.', 'Quán chay hiện đại', 'Cơm gạo lứt xào nấm đậu hũ, Salad bơ sốt chanh leo, Đậu hũ chiên sả ớt, Súp bí đỏ hạt điều', NOW()),
(6, 'Quán Chay Tâm An', '48 Lê Duẩn, Hải Châu, Đà Nẵng', 16.069700, 108.219500, 'Địa chỉ ẩm thực thuần chay quen thuộc tại trung tâm Đà Nẵng, giá cả hợp lý, món ăn phong phú đậm hương vị miền Trung.', 'Quán chay truyền thống', 'Mì Quảng chay nấm đậu, Bún riêu chay miền Trung, Bánh xèo chay giòn rụm, Canh rong biển đậu non', NOW());
